<section class="hero mb-4"><div class="row align-items-end"><div class="col-lg-8"><div class="eyebrow mb-3">A visual memory archive</div><h1 class="display-title mb-4">Stories worth<br>remembering.</h1><p class="lead mb-4 text-white-50">Alzikrayat is a thoughtful photo-sharing space for the moments, places, and people that stay with us.</p><a class="btn btn-gold btn-lg" href="<?= baseUrl('photos') ?>">Explore the gallery</a></div><div class="col-lg-4 mt-4 mt-lg-0"><div class="border-start border-light border-opacity-25 ps-4"><div class="small text-white-50 mb-2">Built for the course project</div><div class="h5">Custom MVC · Manual routing · MySQL</div></div></div></div></section><div class="row g-3 mb-5"><?php foreach([['Users',$stats['users']],['Photos',$stats['photos']],['Comments',$stats['comments']]] as $stat): ?><div class="col-md-4"><div class="stat-card"><div class="text-secondary small text-uppercase fw-bold"><?= e($stat[0]) ?></div><div class="stat-number"><?= e((string)$stat[1]) ?></div><div class="small text-secondary">Growing with every memory</div></div></div><?php endforeach; ?></div><section class="row align-items-center g-4"><div class="col-md-7"><div class="eyebrow">A calm place to share</div><h2 class="mt-2">Keep the context, not only the image.</h2><p class="text-secondary">Upload a photograph with its title, story, and conversation. Every record is connected through a normalized relational database and protected by server-side validation.</p></div><div class="col-md-5"><div class="panel p-4"><h3 class="h5">Ready to contribute?</h3><p class="text-secondary mb-3">Create an account to upload photos and join the conversation.</p><a href="<?= baseUrl(currentUser()?'photo/create':'register') ?>" class="btn btn-dark"><?= currentUser()?'Upload a photo':'Create an account' ?></a></div></div></section>
